using System.Windows; namespace JASS.Bookmark.Master; public partial class CollectionEditor:Window{public string CollectionName=>NameBox.Text.Trim();public string Description=>DescriptionBox.Text.Trim();public CollectionEditor(){InitializeComponent();Owner=Application.Current.MainWindow;}void Save_Click(object s,RoutedEventArgs e){if(string.IsNullOrWhiteSpace(CollectionName)){MessageBox.Show("Enter a collection name.");return;}DialogResult=true;}void Cancel_Click(object s,RoutedEventArgs e){DialogResult=false;}}
